# This code has been fully generated by an AI.
"""EdgeTAM: Maske bei der Registrierung und laufendes Tracking beider Roboter mit eigenem Gedächtnis.

Das Modell merkt sich pro Roboter, wie er aussieht. Hier kommen die Regeln dazu, die verhindern, dass
dieses Gedächtnis bei Berührung, Händen oder Bildfehlern auf den Gegner oder fremde Teile wandert.
"""

import logging
import threading

import cv2
import numpy as np
import torch
import torch.nn.functional as F
from PIL import Image

from .tracking import NO_LOGIT, Track, exclusive, keep_group, plausible, should_swap

log = logging.getLogger(__name__)

# Mehr Bilder schaut das Modell ohnehin nicht zurück; Älteres würde nur Speicher füllen.
KEEP_FRAMES = 16
# Zellen im 256er-Raster, ab denen zwei Masken als berührend gelten.
CONTACT_CELLS = 2


def pick_device() -> tuple[str, str]:
    if torch.cuda.is_available():
        return "cuda", f"GPU: {torch.cuda.get_device_name(0)}"
    return "cpu", "CPU (langsam)"


def descriptor(feats: torch.Tensor, low_res: np.ndarray) -> np.ndarray | None:
    """Aussehen eines Roboters als gemittelter Bildmerkmal-Vektor unter seiner Maske."""
    grid = feats.shape[0]
    side = int(round(grid ** 0.5))
    weight = cv2.resize(low_res.astype(np.float32), (side, side), interpolation=cv2.INTER_AREA)
    if weight.sum() < 1e-3:
        return None
    f = feats[:, 0].float().cpu().numpy()
    vec = (weight.reshape(-1, 1) * f).sum(axis=0) / weight.sum()
    return vec / (np.linalg.norm(vec) + 1e-6)


def _uniform_scores(use_mask_as_output):
    """Maskeneingabe liefert die Objekt-Wertung eine Dimension flacher als normales Tracking.

    Transformers stolpert sonst, wenn ein neuer Roboter auf einem Bild angelegt wird, auf dem der
    andere schon verfolgt wird (torch.cat in EdgeTamVideoModel.forward).
    """

    def wrapped(*args, **kwargs):
        out = use_mask_as_output(*args, **kwargs)
        if out.object_score_logits.dim() == 2:
            out.object_score_logits = out.object_score_logits[..., None]
        return out

    return wrapped


class Segmenter:
    def __init__(self, model_id: str, threads: int = 0):
        self._model_id = model_id
        self._threads = threads
        self._lock = threading.Lock()
        self._model = None
        self._proc = None
        self.device, self.device_label = pick_device()
        self.ready = threading.Event()
        self.error: str | None = None
        self._session = None
        self._idx = -1
        self._ref_area: dict[int, float] = {}
        self._ref_desc: dict[int, np.ndarray] = {}
        self._prev: dict[int, np.ndarray] = {}
        self._pending = False

    def load(self) -> None:
        try:
            from transformers import EdgeTamVideoModel, Sam2VideoProcessor

            if self._threads:
                torch.set_num_threads(self._threads)
            if self.device == "cuda":
                # TF32 ist auf aktuellen Karten deutlich schneller und für Masken genau genug.
                torch.set_float32_matmul_precision("high")
            model = EdgeTamVideoModel.from_pretrained(self._model_id)
            self._model = model.to(self.device, torch.float32).eval()
            self._model._use_mask_as_output = _uniform_scores(self._model._use_mask_as_output)
            self._proc = Sam2VideoProcessor.from_pretrained(self._model_id)
            log.info("EdgeTAM läuft auf %s", self.device_label)
            self.ready.set()
        except Exception as exc:  # noqa: BLE001 – Fehler landet als Klartext in der Bedienung.
            log.exception("EdgeTAM konnte nicht geladen werden")
            self.error = f"Segmentierungsmodell nicht geladen: {exc}"

    def _new_session(self):
        return self._proc.init_video_session(inference_device=self.device, dtype=torch.float32)

    def _inputs(self, bgr: np.ndarray):
        return self._proc(images=Image.fromarray(bgr[..., ::-1]), device=self.device, return_tensors="pt")

    def _full_res(self, low_res: torch.Tensor, inputs) -> np.ndarray:
        masks = self._proc.post_process_masks([low_res.float()], original_sizes=inputs.original_sizes,
                                              binarize=True)[0]
        return masks[:, 0].cpu().numpy().astype(bool)

    @torch.inference_mode()
    def predict(self, bgr: np.ndarray, box: list[float] | None, points: list[tuple[float, float, int]]
                ) -> np.ndarray:
        """Einzelbild-Maske für die Registrierung; Punkte als (x, y, 1=dazu/0=weg)."""
        with self._lock:
            session = self._new_session()
            inputs = self._inputs(bgr)
            kwargs = {}
            if box is not None:
                kwargs["input_boxes"] = [[box]]
            if points:
                kwargs["input_points"] = [[[[x, y] for x, y, _ in points]]]
                kwargs["input_labels"] = [[[label for _, _, label in points]]]
            self._proc.add_inputs_to_inference_session(
                inference_session=session, frame_idx=0, obj_ids=1,
                original_size=inputs.original_sizes[0], **kwargs)
            out = self._model(inference_session=session, frame=inputs.pixel_values[0])
            return self._full_res(out.pred_masks, inputs)[0]

    # ---------- Laufendes Tracking ----------

    def reset_tracking(self) -> None:
        with self._lock:
            self._session = None
            self._idx = -1
            self._ref_area.clear()
            self._ref_desc.clear()
            self._prev.clear()
            self._pending = False

    @torch.inference_mode()
    def add_object(self, obj_id: int, bgr: np.ndarray, mask: np.ndarray) -> None:
        """Bestätigte Registrierungsmaske wird zum festen Ankerbild dieses Roboters."""
        with self._lock:
            if self._session is None:
                self._session = self._new_session()
            self._idx += 1
            inputs = self._inputs(bgr)
            self._proc.add_inputs_to_inference_session(
                inference_session=self._session, frame_idx=self._idx, obj_ids=obj_id, input_masks=[mask])
            out = self._model(inference_session=self._session, frame_idx=self._idx,
                              frame=inputs.pixel_values[0])
            self._clean(out, new=obj_id)
            self._prune()

    @torch.inference_mode()
    def track(self, bgr: np.ndarray) -> dict[int, Track]:
        with self._lock:
            if self._session is None:
                return {}
            self._idx += 1
            inputs = self._inputs(bgr)
            out = self._model(inference_session=self._session, frame_idx=self._idx,
                              frame=inputs.pixel_values[0])
            ids, logits, ok = self._clean(out, new=None)
            if self._swap_needed(ids, logits, ok):
                logits = logits[::-1].copy()
                self._reanchor(ids, logits)
                log.info("Roboter nach Berührung vertauscht erkannt, Identitäten korrigiert")
            self._prune()
            masks = self._full_res(torch.from_numpy(logits[:, None]), inputs)
            return {oid: Track(masks[i], ok[i]) for i, oid in enumerate(ids)}

    def _clean(self, out, new: int | None) -> tuple[list[int], np.ndarray, list[bool]]:
        s, idx = self._session, self._idx
        ids = list(out.object_ids)
        raw = out.pred_masks[:, 0].float().cpu().numpy()
        scores = out.object_score_logits.reshape(-1).float().cpu().numpy()
        logits = exclusive(raw)
        feats, _ = self._model._prepare_vision_features(s, idx, 1)
        ok = []
        for i, oid in enumerate(ids):
            mask = keep_group(logits[i] > 0, self._prev.get(oid))
            logits[i][~mask] = np.minimum(logits[i][~mask], NO_LOGIT)
            if oid == new:
                self._ref_area[oid] = float(mask.sum())
                self._ref_desc[oid] = descriptor(feats[-1], mask)
                self._prev[oid] = mask
                ok.append(True)
                continue
            good = bool(scores[i] > 0) and plausible(float(mask.sum()), self._ref_area[oid])
            ok.append(good)
            obj_idx = s.obj_id_to_idx(oid)
            if good:
                self._prev[oid] = mask
                if ((raw[i] > 0) != mask).any():
                    self._remember(obj_idx, feats[-1], logits[i])
            else:
                # Ein Bild mit Hand, Gegner oder ohne Roboter darf das Gedächtnis nicht prägen.
                s.output_dict_per_obj[obj_idx]["non_cond_frame_outputs"].pop(idx, None)
                s.frames_tracked_per_obj[obj_idx].pop(idx, None)
            if scores[i] <= 0:
                logits[i] = np.minimum(logits[i], NO_LOGIT)
        return ids, logits, ok

    def _remember(self, obj_idx: int, feats: torch.Tensor, logits: np.ndarray) -> None:
        """Gedächtnis dieses Bildes aus der bereinigten Maske neu schreiben."""
        s = self._session
        entry = s.output_dict_per_obj[obj_idx]["non_cond_frame_outputs"].get(self._idx)
        if entry is None:
            return
        low = torch.from_numpy(logits)[None, None].to(self.device)
        size = self._model.config.image_size
        high = F.interpolate(low, (size, size), mode="bilinear", align_corners=False)
        features, pos = self._model._encode_new_memory(
            current_vision_feats=feats, pred_masks_high_res=high,
            object_score_logits=entry["object_score_logits"], is_mask_from_pts=False)
        entry["pred_masks"] = low.to(s.inference_state_device)
        entry["maskmem_features"] = features.to(s.inference_state_device)
        entry["maskmem_pos_enc"] = pos.to(s.inference_state_device)

    def _swap_needed(self, ids: list[int], logits: np.ndarray, ok: list[bool]) -> bool:
        if len(ids) != 2:
            return False
        a, b = logits[0] > 0, logits[1] > 0
        k = 2 * CONTACT_CELLS + 1
        touching = a.any() and b.any() and bool(
            (cv2.dilate(a.astype(np.uint8), np.ones((k, k), np.uint8)).astype(bool) & b).any())
        if touching:
            self._pending = True
            return False
        if not (self._pending and all(ok)):
            return False
        # Erst wenn beide wieder frei und sauber sind, lässt sich das Aussehen ehrlich vergleichen.
        self._pending = False
        feats, _ = self._model._prepare_vision_features(self._session, self._idx, 1)
        now = [descriptor(feats[-1], m) for m in (a, b)]
        refs = [self._ref_desc.get(oid) for oid in ids]
        if any(v is None for v in now + refs):
            return False
        sim = np.array([[float(now[i] @ refs[j]) for j in range(2)] for i in range(2)])
        return should_swap(sim)

    def _reanchor(self, ids: list[int], logits: np.ndarray) -> None:
        """Vertauschte Erinnerungen verwerfen und die richtigen Masken als neue Ankerbilder setzen."""
        s, idx = self._session, self._idx
        for oid in ids:
            obj_idx = s.obj_id_to_idx(oid)
            s.output_dict_per_obj[obj_idx]["non_cond_frame_outputs"].clear()
            s.frames_tracked_per_obj[obj_idx].clear()
        masks = [torch.from_numpy(m > 0) for m in logits]
        # Eine Kopie: HF übernimmt die Liste als obj_with_new_inputs und leert sie nach dem Lauf.
        self._proc.add_inputs_to_inference_session(
            inference_session=s, frame_idx=idx, obj_ids=list(ids), input_masks=masks)
        self._model(inference_session=s, frame_idx=idx)
        for i, oid in enumerate(ids):
            self._prev[oid] = logits[i] > 0

    def _prune(self) -> None:
        s, idx = self._session, self._idx
        oldest = idx - KEEP_FRAMES
        for obj_idx in range(s.get_obj_num()):
            non_cond = s.output_dict_per_obj[obj_idx]["non_cond_frame_outputs"]
            for key in [k for k in non_cond if k < oldest]:
                del non_cond[key]
            tracked = s.frames_tracked_per_obj[obj_idx]
            for key in [k for k in tracked if k < oldest]:
                del tracked[key]
            s.mask_inputs_per_obj[obj_idx].clear()
        for key in [k for k in s.processed_frames if k != idx]:
            del s.processed_frames[key]
